const fs=require('node:fs');const path=require('node:path');const {randomUUID}=require('node:crypto');const {planDirectory,applyPlan,stageDirectory}=require('./core.cjs');const {noArgs}=require('./boundary.cjs');
function createTool({dataDir,dialog,win}){fs.mkdirSync(dataDir,{recursive:true});let root=null,plan=null;const view=()=>({workspace:root,items:plan.items.map(({source,target})=>({source,target}))});
function manifest(){const file=path.join(dataDir,'session-'+randomUUID()+'.json');const tmp=file+'.tmp';fs.writeFileSync(tmp,JSON.stringify({schemaVersion:1,workspace:root}));fs.renameSync(tmp,file);}
return {handlers:{sample(v){noArgs(v);root=path.join(dataDir,'sample-'+randomUUID());fs.mkdirSync(root);for(const [name,text] of [['收據.txt','測試收據'],['note.md','# 測試'],['photo.png','這是測試文字，不是真圖片'],['archive.bin','demo']])fs.writeFileSync(path.join(root,name),text);manifest();plan=planDirectory(root);return view();},async choose(v){noArgs(v);const r=await dialog.showOpenDialog(win,{properties:['openDirectory']});if(r.canceled)return {canceled:true};plan=null;const next=path.join(dataDir,'copy-'+randomUUID());stageDirectory(r.filePaths[0],next);root=next;manifest();plan=planDirectory(root);return view();},preview(v){noArgs(v);if(!root)throw Error('INVALID');plan=planDirectory(root);return view();},async apply(v){noArgs(v);if(!plan)throw Error('INVALID');const r=await dialog.showMessageBox(win,{type:'warning',buttons:['取消','整理工作副本'],defaultId:0,cancelId:0,message:`即將整理 ${plan.items.length} 個工作副本。原始選取資料夾保持不變。`});if(r.response!==1)return {canceled:true};const current=plan;plan=null;return {...applyPlan(current),workspace:root};}}};}
module.exports={createTool};

